Lemma tg_rid1 :
  (forall op l, g_op TG op = Some l -> (count_occ Z.eq_dec l OT_RESULT_ID <= 1)%nat)
  /\ (forall t v l, g_operand TG t v = Some l -> ~ In OT_RESULT_ID l)
